import importlib
for mod in ['pandas', 'openpyxl', 'xlsxwriter', 'xlrd', 'pyxlsb', 'odf']:
    try:
        m = importlib.import_module(mod)
        print(mod, "OK", getattr(m, '__version__', ''))
    except Exception as e:
        print(mod, "MISSING", type(e).__name__)

import zipfile, re

with zipfile.ZipFile('sales_data.xlsx') as z:
    print("=== ZIP CONTENTS ===")
    for n in z.namelist():
        print(n)
    print("\n=== workbook.xml (rels names) ===")
    try:
        print(z.read('xl/workbook.xml').decode('utf-8'))
    except KeyError as e:
        print("missing", e)
    print("\n=== workbook rels ===")
    try:
        print(z.read('xl/_rels/workbook.xml.rels').decode('utf-8'))
    except KeyError as e:
        print("missing", e)
    print("\n=== sharedStrings (first 3000 chars) ===")
    try:
        print(z.read('xl/sharedStrings.xml').decode('utf-8')[:3000])
    except KeyError as e:
        print("missing", e)

import os

for root, dirs, files in os.walk('.'):
    depth = root.count(os.sep)
    if depth > 4:
        continue
    for f in files:
        p = os.path.join(root, f)
        print(p)

